def cached(cache, key=hashkey, lock=None):
    """
    Returns a decorator function that saves the results in the cache
    """
    def decorator(func):
        @cachetools.cached(cache, key=key)
        def cached_func(*args, **kwargs):
            if lock:
                with lock:
                    return func(*args, **kwargs)
            else:
                return func(*args, **kwargs)
        return cached_func
