# Function to get cell color based on value
def get_cell_color(value):
    colors = {
        0: (205, 193, 180),
        2: (238, 228, 218),
        4: (237, 224, 200),
        8: (242, 177, 121),
        16: (245, 149, 99),
        32: (246, 124, 95),
        64: (246, 94, 59),
        128: (237, 207, 114),
        256: (237, 204, 97),
        512: (237, 200, 80),
        1024: (237, 197, 63),
        2048: (237, 194, 46)
    }
    return colors.get(value, BLACK)

# Function to add a new tile
def add_new_tile():
    empty_cells = [(row, col) for row in range(GRID_SIZE) for col in range(GRID_SIZE) if board[row][col] == 0]
    if empty_cells:
        row, col = empty_cells[pygame.random.randint(0, len(empty_cells) - 1)]
        board[row][col] = 2 if pygame.random.randint(0, 9) > 1 else 4

# Function to check if the game is over
def is_game_over():
    for row in range(GRID_SIZE):
        for col in range(GRID_SIZE):
            if board[row][col] == 0:
                return False
            if row < GRID_SIZE - 1 and board[row][col] == board[row + 1][col]:
                return False
            if col < GRID_SIZE - 1 and board[row][col] == board[row][col + 1]:
                return False
    return True

# Function to handle user input
def handle_events():
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            pygame.quit()
            sys.exit()
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_UP:
                move_up()
            elif event.key == pygame.K_DOWN:
                move_down()
            elif event.key == pygame.K_LEFT:
                move_left()
            elif event.key == pygame.K_RIGHT:
                move_right()
            elif event.key == pygame.K_r:
                restart_game()

