    global score
    rows_moved = False
    for col in range(GRID_SIZE):
        row = 0
        while row < GRID_SIZE - 1:
            if board[row][col] == 0:
                current_row = row + 1
                while current_row < GRID_SIZE and board[current_row][col] == 0:
                    current_row += 1
                if current_row < GRID_SIZE:
                    board[row][col], board[current_row][col] = board[current_row][col], board[row][col]
                    rows_moved = True
            if board[row][col] != 0:
                current_row = row
                while current_row > 0 and board[current_row - 1][col] == 0:
                    current_row -= 1
                if current_row > 0 and board[current_row - 1][col] == board[current_row][col]:
                    board[current_row - 1][col] *= 2
                    score += board[current_row][col]
                    board[current_row][col] = 0
            row += 1
    if rows_moved:
        add_new_tile()

