from typing import List, Dict

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Sums the values for each key across a list of dictionaries.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries where each dictionary has string keys and integer values.

    Returns:
        Dict[str, int]: A new dictionary with the summed values for each key.
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

